import numpy as np
X={'1':np.ones_like(x),'x':x,'x2':x**2,'x3':x**3,'sinx':np.sin(x),'cosx':np.cos(x),'x/(1+x2)':x/(1+x**2),'xcosx':x*np.cos(x)}
