C={f'{a}*{b}':X[a]*Vv[b] for a in X for b in Vv}
names=list(C)
def err(sel):
    M=np.column_stack([C[n] for n in sel]); c,_,_,_=np.linalg.lstsq(M,dv_dt,rcond=None)
    return np.mean((dv_dt-M@c)**2)/np.var(dv_dt), c
